// --- RENDERIZAÇÃO DOS CARDS ---
function renderizarItensWaterlow() {
const container = document.getElementById("waterlowForm");
container.innerHTML = "";

// 1. Renderiza os Selects Obrigatórios
ITENS_WATERLOW.forEach((item) => {
let optsHtml = "";
item.opts.forEach((op) => {
optsHtml += `<option value="${op.val}" ${op.val === "" ? "चयन करें..." : ""}>${op.text}</option>`;
});

const div = document.createElement("div");
div.className = "item-card";
div.id = `card_${item.id}`;
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label for="${item.id}" class="text-[13px] font-bold text-slate-800">${item.label} <span class="text-red-500">*</span></label>
<span id="badge_${item.id}" class="item-badge">--/${item.max}</span>
</div>
<p class="text-[11px] text-slate-500 mb-3 leading-snug h-8">${item.desc}</p>
<select id="${item.id}" class="item-select अनिवार्य">${optsHtml}</select>
<div class="mini-bar-wrap">
<div id="bar_${item.id}" class="mini-bar-fill" style="width: 0%;"></div>
</div>
`;
container.appendChild(div);

const el = document.getElementById(item.id);
el.addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarCardIndividual(item.id, item.max);
});

el.addEventListener('change', startTimer, {once: true});
el.addEventListener("wheel", function(e) { e.preventDefault(); this.blur(); });
});

// 2. Renderiza os Checkboxes Opcionais (Riscos Especiais)
RISCOS_ESPECIAIS.forEach((grupo) => {
const div = document.createElement("div");
div.className = "item-card col-span-full"; 
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label class="text-[14px] font-bold text-navy">${grupo.label}</label>
<span class="text-[10px] bg-slate-100 text-slate-600 px-2 py-1 rounded font-bold uppercase tracking-wider">वैकल्पिक (बहुविकल्पीय)</span>
</div>
<p class="text-[11px] text-slate-500 mb-4 leading-snug">${grupo.desc}</p>
<div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3" id="group_${grupo.id}">
</div>
`;
container.appendChild(div);

const groupContainer = document.getElementById(`group_${grupo.id}`);
grupo.opts.forEach((op) => {
const label = document.createElement("label");
label.className = "waterlow-checkbox-label";
label.innerHTML = `
<input type="checkbox" value="${op.val}" id="${op.id_sub}" data-text="${op.text.split('(')[0].trim()}" class="waterlow-checkbox">
<span>${op.text}</span>
`;
groupContainer.appendChild(label);

// Evento para iniciar cronômetro também nos checkboxes
label.querySelector("input").addEventListener('change', startTimer, {once: true});
});
});
}

// --- ATUALIZAR STATUS DE UM CARD ESPECÍFICO (Selects) ---
function atualizarCardIndividual(id, max) {
const select = document.getElementById(id);
const valStr = select.value;
if (valStr === "") return;
const val = parseInt(valStr);
// Barra sempre visível: mínimo 8% para mostrar a cor
const pct = Math.max((val / max) * 100, 8);

const badge = document.getElementById(`badge_${id}`);
const bar = document.getElementById(`bar_${id}`);

badge.textContent = `${val}/${max}`;
bar.style.width = `${pct}%`;

// Cores baseadas na pontuação (Waterlow: 0 é verde, maior é pior/vermelho)
let cor = "#16a34a"; // Verde (0)
if (pct > 0 && pct <= 33) cor = "#eab308"; // Amarelo
else if (pct > 33 && pct <= 66) cor = "#f97316"; // Laranja
else if (pct > 66) cor = "#e11d48"; // Vermelho

bar.style.backgroundColor = cor;

// Badge também muda de cor conforme escore
badge.style.backgroundColor = cor === "transparent" ? "" : `${cor}15`;
badge.style.color = cor === "transparent" ? "" : cor;
badge.style.borderColor = cor === "transparent" ? "" : `${cor}30`;

atualizarBarraGlobal();
}

// --- BARRA FLUTUANTE GLOBAL E CONTADOR (Baseado nos 4 selects obrigatórios) ---
function atualizarBarraGlobal() {
let preenchidos = 0;
const obrigatorios = document.querySelectorAll(".obrigatorio");
obrigatorios.forEach((i) => {
if (i.value !== "") preenchidos++;
});

const pctGlobal = (preenchidos / 4) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/4`;
}

// --- LÓGICA DADOS DO PACIENTE (TOGGLE) ---
document.getElementById("btnToggleDados").addEventListener("click", function () {
const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
const subtitle = document.getElementById("dadosSubtitle");

if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
subtitle.textContent = "मेडिकल रिकॉर्ड/पीडीएफ रिपोर्ट के लिए भरें";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
subtitle.textContent = "पैनल छिपाएँ";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// --- CÁLCULO E RESULTADO ---
const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = ["pele", "integridade", "risco"];
let primeiroErro = null;

// 1. Processar Selects Obrigatórios
ITENS_WATERLOW.forEach((item) => {
const selectElement = document.getElementById(item.id);
const selectVal = selectElement.value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
dominiosValores.push({ nome: item.label, obtido: 0, text: "भरा नहीं गया" });
} else {
document.getElementById(`card_${item.id}`).classList.remove("error");
const val = parseInt(selectVal);
somaTotal += val;
const textoSelect = selectElement.options[selectElement.selectedIndex].text.replace(/\s*\([^)]*\)$/, ""); // Remove "(x)"
dominiosValores.push({ nome: item.label.replace(/^\d+\.\s*/, ""), obtido: val, text: textoSelect });

// Alimentando palavras-chave para NANDA
if (val > 0) {
if (item.id === "pele") diagnosticosKeywords.push("tecido", "pressão");
if (item.id === "mobilidade") diagnosticosKeywords.push("mobilidade", "queda", "transferência");
if (item.id === "debito") diagnosticosKeywords.push("neurológico", "sensorial", "conhecimento");
if (item.id === "continencia") diagnosticosKeywords.push("eliminação", "urinária", "intestinal");
}
}
});

if (incompleto) {
const msgErro = document.getElementById("msgValidacaoErro");
msgErro.style.display = "block";
if (primeiroErro) {
primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
}
return;
}

document.getElementById("msgValidacaoErro").style.display = "none";
clearInterval(timerInterval);

// 2. Processar Checkboxes Opcionais
const checkboxes = document.querySelectorAll(".waterlow-checkbox:checked");
let textosExtras = [];
checkboxes.forEach((cb) => {
const val = parseInt(cb.value);
somaTotal += val;
textosExtras.push(cb.getAttribute("data-text"));
diagnosticosKeywords.push("nutrição", "perfusão", "proteção"); // Adiciona keywords genéricas se marcou extras
});

if (textosExtras.length > 0) {
dominiosValores.push({ nome: "पहचाने गए विशेष जोखिम", obtido: "+"+(somaTotal - dominiosValores.reduce((a,b)=>a+b.obtido,0)), text: textosExtras.join(", ") });
} else {
dominiosValores.push({ nome: "पहचाने गए विशेष जोखिम", obtido: 0, text: "Nenhum" });
}

// Determinar Classificação Waterlow
let classe = "", bgPill = "", recomendacao = "";
if (somaTotal < 10) {
classe = "कम जोखिम"; bgPill = "#16a34a"; // Verde
recomendacao = "न्यूनतम जोखिम। नियमित स्वच्छता देखभाल, बुनियादी गतिशीलता और आवधिक पुनर्मूल्यांकन बनाए रखें।";
} else if (somaTotal <= 14) {
classe = "जोखिम में"; bgPill = "#eab308"; // Amarelo
recomendacao = "रोगी में सक्रिय जोखिम कारक हैं। बुनियादी रोकथाम प्रोटोकॉल शुरू करें, दैनिक त्वचा निरीक्षण और मानक करवट बदलाव करें।";
} else if (somaTotal <= 19) {
classe = "उच्च जोखिम"; bgPill = "#f97316"; // Laranja
recomendacao = "उच्च जोखिम। उन्नत दबाव राहत उपाय, गहन जलयोजन, पोषण नियंत्रण और कठोर स्थिति परिवर्तन लागू करें।";
} else {
classe = "अति उच्च जोखिम"; bgPill = "#e11d48"; // Vermelho
recomendacao = "दबाव अल्सर का अधिकतम जोखिम। आक्रामक रोकथाम प्रोटोकॉल की आवश्यकता है: विशेष गतिशील गद्दे, हर 2 घंटे में कठोर स्थिति परिवर्तन और निरंतर बहु-विषयक पुनर्मूल्यांकन।";
}

// Exibir no Hero Card
document.getElementById("scoreValor").textContent = somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

// Destacar card correspondente no Sidebar
const scpIds = ["scp-baixo", "scp-emrisco", "scp-alto", "scp-altissimo"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

let scpAlvo = null;
if (somaTotal < 10) scpAlvo = document.getElementById("scp-baixo");
else if (somaTotal <= 14) scpAlvo = document.getElementById("scp-emrisco");
else if (somaTotal <= 19) scpAlvo = document.getElementById("scp-alto");
else scpAlvo = document.getElementById("scp-altissimo");

if (scpAlvo) {
scpAlvo.style.transform = "scale(1.03)";
scpAlvo.style.boxShadow = "0 8px 25px rgba(0,0,0,0.25)";
scpAlvo.classList.add("scp-highlight");
}

document.getElementById("resultadoMensagem").innerHTML = `रोगी ने कुल <strong>${somaTotal} अंक</strong> प्राप्त किए।<br><br><strong>कार्रवाई:</strong> ${recomendacao}`;

// Gerar Tabela de Detalhamento
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {

// Cor da linha baseada no fato de ter pontuado ou não
let cor = "#16a34a"; // verde
if (typeof dom.obtido === 'string' || dom.obtido > 0) cor = "#e11d48"; // vermelho se tem ponto ou é a string de soma "+"

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome}</td>
<td class="text-center font-black" style="color: ${cor}">${dom.obtido}</td>
<td>
<span class="text-[12px] font-bold px-3 py-1 rounded-lg inline-block" style="background-color: ${cor}10; color: ${cor}; border: 1px solid ${cor}30">${dom.text}</span>
</td>
`;
tbody.appendChild(tr);
});
document.getElementById("totalObtidoTd").textContent = somaTotal;
document.getElementById("totalObtidoTd").style.color = bgPill;

// Mostrar Seção
resultadoSection.classList.add("visible");
resultadoSection.style.display = "block";
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

// Chamar NANDA
chamarNanda(diagnosticosKeywords);

window.__calcData = { soma: somaTotal, classe, dominios: dominiosValores };
}

async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em" aria-hidden="true"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> NANDA-I डेटाबेस से जानकारी प्राप्त की जा रही है...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("फेच त्रुटि");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

// Dedup
const prefixosIgnorar = ["का जोखिम", "के लिए तैयारी", "सिंड्रोम", "की प्रवृत्ति", "के लिए तैयारी", "का जोखिम"];
const temasUsados = new Set();
const topDiversos = [];

function extrairTema(titulo) {
let t = titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
for (const p of prefixosIgnorar) {
if (t.startsWith(p)) { t = t.slice(p.length).trim(); break; }
}
const palavras = t.split(/\s+/).filter(w => w.length > 3 && !["para", "com", "sem", "como", "dos", "das", "que", "não", "nao", "melhorada", "melhorado", "prejudicada", "prejudicado", "adulto", "criança", "neonatal", "idoso", "lactente", "feminino", "masculino"].includes(w));
return palavras.slice(0, 4).join(" ");
}

for (const d of pontuados) {
const tema = extrairTema(d.diagnostico);
if (!temasUsados.has(tema) && !temasUsados.has(d.codigo)) {
temasUsados.add(tema);
temasUsados.add(d.codigo);
topDiversos.push(d);
}
if (topDiversos.length >= 6) break;
}

if (topDiversos.length > 0) {
lista.innerHTML = "";
topDiversos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">वर्तमान चयन के साथ कोई महत्वपूर्ण प्राथमिक निदान जुड़ा नहीं है।</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">NANDA डेटाबेस अस्थायी रूप से अनुपलब्ध है।</li>';
}
}

