doc.text(String(data.soma) + " अंक", W / 2, y + 17, { align: "center" });
y += 28;

// Status Pill
let pillColor = [22, 163, 74]; // Verde
if (data.soma >= 10 && data.soma <= 14) pillColor = [234, 179, 8]; // Amarelo
else if (data.soma >= 15 && data.soma <= 19) pillColor = [249, 115, 22]; // Laranja
else if (data.soma >= 20) pillColor = [225, 29, 72]; // Vermelho

doc.setFillColor(...pillColor);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text(data.classe.toUpperCase(), W / 2, y + 5.5, { align: "center" });
y += 16;

// Tabela AutoTable
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.text("नैदानिक मूल्यांकन रिकॉर्ड", marginL + 4, y + 5.5);
